 [$h,$rows,$delimiter]=csvAll($productFile);$total=count($rows);$offset=max(0,(int)($_GET['offset']??0));$limit=min(1000,max(100,(int)($_GET['limit']??500)));$slice=array_slice($rows,$offset,$limit);
