 $categories=[];if($categoryFile){[$ch,$cr]=csvAll($categoryFile);$cid=col($ch,['id','код','category_id','id категории']);$cn=col($ch,['name','title','наименование','название','категория']);$cp=col($ch,['parent_id','родитель','parent','id родителя']);if($cn===null)$cn=inferTextCol($ch,$cr);foreach($cr as $r){$key=val($r,$cid);$name=val($r,$cn);if($name==='')continue;if($key==='')$key=$name;$categories[$key]=['name'=>$name,'parent'=>val($r,$cp)];}}
