 $ins=$pdo->prepare('INSERT INTO products(source_hash,title,price_rub,availability,category_path,specs,description,images,is_active) VALUES(?,?,?,?,?,?,?,?,1)');$upd=$pdo->prepare('UPDATE products SET source_hash=?,title=?,price_rub=?,availability=?,category_path=?,specs=?,description=?,images=?,is_active=1,updated_at=CURRENT_TIMESTAMP WHERE id=?');
 $created=0;$updated=0;$reusedImages=0;$pdo->beginTransaction();
